function solve(num) {
  if (num <= 0) return "";
  const places = [
    ["", "M", "MM", "MMM"],
    ["", "C", "CC", "CCC", "CD", "D", "DC", "DCC", "DCCC", "CM"],
    ["", "X", "XX", "XXX", "XL", "L", "LX", "LXX", "LXXX", "XC"],
    ["", "I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"],
  ];
  const digits = String(num).split("").map(Number);
  let out = "";
  for (let i = 0; i < digits.length; i++) {
    const place = 4 - digits.length + i;
    if (place < 0) continue;
    const glyph = places[place][digits[i]];
    if (glyph) out += glyph;
  }
  return out;
}

function solve(num) {
  const values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1];
  const glyph = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"];
  let out = "";
  for (let i = 0; i < values.length; i++) {
    while (num >= values[i]) {
      out += glyph[i];
      num -= values[i];
    }
  }
  return out;
}
